/** Trusted React renderer for this Rich Catalog component. */
import React from "react"; import {useRichComponent} from "../../../binding.js"; export function Renderer({surface,component,basePath="/"}){const {properties:p}=useRichComponent(surface,component,basePath);return <section className="anu-rich-timeline">{p.title&&<h3>{p.title}</h3>}<ol>{(p.items??[]).map(x=><li key={x.id}><span className="timeline-icon">{x.icon??"●"}</span><div>{x.time&&<time>{x.time}</time>}<strong>{x.title}</strong>{x.subtitle&&<p>{x.subtitle}</p>}{x.status&&<small>{x.status}</small>}</div></li>)}</ol></section>}
